// Estado global de la aplicación
let appState = {
  config: { ...DEFAULT_CONFIG },
  clients: [],
  transactions: [],
  currentTab: 'clientes',
  activeClientIdForReport: null,
  activeTicketMode: 'ticket' // 'ticket' (80mm) o 'completo' (A4/Carta)
};

// --- FUNCIONES DE PERSISTENCIA ---
function loadData() {
  try {
    const savedConfig = localStorage.getItem(STORAGE_KEYS.CONFIG);
    const savedClients = localStorage.getItem(STORAGE_KEYS.CLIENTS);
    const savedTx = localStorage.getItem(STORAGE_KEYS.TRANSACTIONS);

    appState.config = savedConfig ? JSON.parse(savedConfig) : { ...DEFAULT_CONFIG };
    appState.clients = savedClients ? JSON.parse(savedClients) : [...INITIAL_CLIENTS];
    appState.transactions = savedTx ? JSON.parse(savedTx) : [...INITIAL_TRANSACTIONS];

    // Si era la primera vez, guardar los valores iniciales
    if (!savedConfig) saveData();
  } catch (error) {
    console.error('Error cargando datos locales:', error);
    appState.config = { ...DEFAULT_CONFIG };
    appState.clients = [...INITIAL_CLIENTS];
    appState.transactions = [...INITIAL_TRANSACTIONS];
  }
}

function saveData() {
  try {
    localStorage.setItem(STORAGE_KEYS.CONFIG, JSON.stringify(appState.config));
    localStorage.setItem(STORAGE_KEYS.CLIENTS, JSON.stringify(appState.clients));
    localStorage.setItem(STORAGE_KEYS.TRANSACTIONS, JSON.stringify(appState.transactions));
  } catch (error) {
    console.error('Error guardando en almacenamiento local:', error);
    showToast('Error al guardar datos en el navegador', 'error');
  }
}

// --- CÁLCULOS FINANCIEROS POR CLIENTE ---
function getClientBalance(clientId) {
  const clientTx = appState.transactions.filter(t => t.clientId === clientId);
  const totalCredit = clientTx
    .filter(t => t.type === 'credit')
    .reduce((sum, t) => sum + Number(t.amount || 0), 0);
  const totalPaid = clientTx
    .filter(t => t.type === 'payment')
    .reduce((sum, t) => sum + Number(t.amount || 0), 0);

  const balance = totalCredit - totalPaid;
  const lastCredit = clientTx
    .filter(t => t.type === 'credit')
    .sort((a, b) => new Date(b.date + ' ' + (b.time || '00:00')) - new Date(a.date + ' ' + (a.time || '00:00')))[0];

  return {
    totalCredit,
    totalPaid,
    balance: Math.round(balance * 100) / 100,
    lastCreditDate: lastCredit ? lastCredit.date : null,
    pendingTransactionsCount: clientTx.filter(t => t.type === 'credit').length
  };
}

function formatCurrency(amount) {
  const curr = appState.config.currency || '$';
  return `${curr} ${Number(amount || 0).toLocaleString('es-MX', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
}

function formatDate(dateStr) {
  if (!dateStr) return 'N/A';
  const parts = dateStr.split('-');
  if (parts.length === 3) {
    return `${parts[2]}/${parts[1]}/${parts[0]}`;
  }
  return dateStr;
}

// --- NOTIFICACIONES / TOASTS ---
function showToast(message, type = 'success') {
  const container = document.getElementById('toast-container');
  if (!container) return;

  const toast = document.createElement('div');
  const bgClass = type === 'error' ? 'bg-red-600' : type === 'warning' ? 'bg-amber-600' : 'bg-emerald-600';
  const icon = type === 'error' ? '⚠️' : type === 'warning' ? '⚡' : '✅';

  toast.className = `${bgClass} text-white px-4 py-3 rounded-xl shadow-lg flex items-center space-x-2 text-sm font-medium transition-all duration-300 transform translate-y-2 opacity-0`;
  toast.innerHTML = `<span>${icon}</span> <span>${message}</span>`;

  container.appendChild(toast);
  setTimeout(() => {
    toast.classList.remove('translate-y-2', 'opacity-0');
  }, 10);

  setTimeout(() => {
    toast.classList.add('opacity-0', 'translate-y-2');
    setTimeout(() => toast.remove(), 300);
  }, 3500);
}

// --- NAVEGACIÓN DE PESTAÑAS ---
function switchTab(tabName) {
  appState.currentTab = tabName;
  document.querySelectorAll('.tab-content').forEach(el => el.classList.add('hidden'));
  document.querySelectorAll('.nav-tab-btn').forEach(btn => {
    btn.classList.remove('bg-amber-600', 'text-white', 'shadow-sm');
    btn.classList.add('text-slate-600', 'hover:bg-slate-100');
  });

  const activeContent = document.getElementById(`tab-content-${tabName}`);
  if (activeContent) activeContent.classList.remove('hidden');

  const activeBtn = document.getElementById(`nav-btn-${tabName}`);
  if (activeBtn) {
    activeBtn.classList.add('bg-amber-600', 'text-white', 'shadow-sm');
    activeBtn.classList.remove('text-slate-600', 'hover:bg-slate-100');
  }

  // Actualizaciones de contenido específicas por pestaña
  if (tabName === 'clientes') renderClientsList();
  if (tabName === 'reportes') renderCollectionReport();
  if (tabName === 'configuracion') loadConfigIntoForm();
  if (tabName === 'consumos') populateClientSelects();
  if (tabName === 'abonos') populateClientSelects();
}

// --- RENDERIZADO DEL RESUMEN GLOBAL (TOP BAR / STATS) ---
function updateGlobalStats() {
  let totalPendingDebt = 0;
  let totalDebtorsCount = 0;
  let totalPaidOverall = 0;
  let topDebtor = { name: 'Ninguno', balance: 0 };

  appState.clients.forEach(client => {
    const { balance, totalPaid } = getClientBalance(client.id);
    totalPaidOverall += totalPaid;
    if (balance > 0) {
      totalPendingDebt += balance;
      totalDebtorsCount++;
      if (balance > topDebtor.balance) {
        topDebtor = { name: client.name, balance };
      }
    }
  });

  const statDebtEl = document.getElementById('stat-total-debt');
  const statCountEl = document.getElementById('stat-debtors-count');
  const statPaidEl = document.getElementById('stat-total-paid');
  const businessNameHeader = document.getElementById('header-business-name');

  if (statDebtEl) statDebtEl.textContent = formatCurrency(totalPendingDebt);
  if (statCountEl) statCountEl.textContent = `${totalDebtorsCount} comensal${totalDebtorsCount === 1 ? '' : 'es'}`;
  if (statPaidEl) statPaidEl.textContent = formatCurrency(totalPaidOverall);
  if (businessNameHeader) businessNameHeader.textContent = appState.config.businessName;
}

// --- RENDERIZADO DE CLIENTES ---
function renderClientsList() {
  updateGlobalStats();
  const container = document.getElementById('clients-grid');
  const searchInput = document.getElementById('search-clients-input');
  const filterSelect = document.getElementById('filter-clients-status');

  const query = (searchInput ? searchInput.value : '').toLowerCase().trim();
  const filter = filterSelect ? filterSelect.value : 'all';

  if (!container) return;

  const filteredClients = appState.clients.filter(client => {
    const { balance } = getClientBalance(client.id);
    const matchesSearch = 
      client.name.toLowerCase().includes(query) ||
      (client.alias && client.alias.toLowerCase().includes(query)) ||
      (client.phone && client.phone.toLowerCase().includes(query));

    if (!matchesSearch) return false;

    if (filter === 'debtors') return balance > 0;
    if (filter === 'cleared') return balance <= 0;
    return true;
  });

  // Ordenar: primero los que tienen mayor saldo pendiente
  filteredClients.sort((a, b) => {
    const balA = getClientBalance(a.id).balance;
    const balB = getClientBalance(b.id).balance;
    return balB - balA;
  });

  if (filteredClients.length === 0) {
    container.innerHTML = `
      <div class="col-span-full py-12 text-center bg-white rounded-2xl border border-slate-200">
        <div class="text-4xl mb-3">🔍</div>
        <h4 class="text-base font-semibold text-slate-700">No se encontraron clientes</h4>
        <p class="text-sm text-slate-500 mt-1">Prueba con otro término de búsqueda o agrega un nuevo cliente.</p>
        <button onclick="openModal('modal-add-client')" class="mt-4 px-4 py-2 bg-amber-600 text-white rounded-xl text-sm font-medium hover:bg-amber-700">
          + Agregar Nuevo Cliente
        </button>
      </div>
    `;
    return;
  }

  container.innerHTML = filteredClients.map(client => {
    const { totalCredit, totalPaid, balance, lastCreditDate } = getClientBalance(client.id);

    let badgeHtml = '';
    let cardBorder = 'border-slate-200';
    let balanceColor = 'text-slate-800';

    if (balance > 0) {
      badgeHtml = `<span class="badge-debt px-2.5 py-1 rounded-full text-xs font-semibold">Deuda: ${formatCurrency(balance)}</span>`;
      cardBorder = 'border-red-200 hover:border-red-300';
      balanceColor = 'text-red-600';
    } else if (balance === 0) {
      badgeHtml = `<span class="badge-clean px-2.5 py-1 rounded-full text-xs font-semibold">Al Día (Sin deuda)</span>`;
      balanceColor = 'text-emerald-600';
    } else {
      badgeHtml = `<span class="badge-credit px-2.5 py-1 rounded-full text-xs font-semibold">Saldo a favor: ${formatCurrency(Math.abs(balance))}</span>`;
      balanceColor = 'text-blue-600';
    }

    const cleanPhone = client.phone ? client.phone.replace(/\D/g, '') : '';
    const hasPhone = cleanPhone.length >= 7;

    return `
      <div class="bg-white rounded-2xl border ${cardBorder} p-5 shadow-sm card-hover flex flex-col justify-between">
        <div>
          <!-- Cabecera de tarjeta -->
          <div class="flex items-start justify-between gap-2 mb-3">
            <div>
              <h3 class="font-bold text-slate-900 text-base flex items-center gap-1.5">
                <span>${escapeHtml(client.name)}</span>
              </h3>
              ${client.alias ? `<p class="text-xs text-amber-700 font-medium bg-amber-50 inline-block px-2 py-0.5 rounded mt-0.5">🏷️ ${escapeHtml(client.alias)}</p>` : ''}
            </div>
            ${badgeHtml}
          </div>

          <!-- Detalles de contacto -->
          <div class="space-y-1.5 text-xs text-slate-600 mb-4">
            ${client.phone ? `
              <div class="flex items-center gap-1.5">
                <span class="text-slate-400">📞</span>
                <span class="font-mono text-slate-700 font-medium">${escapeHtml(client.phone)}</span>
              </div>
            ` : '<div class="text-slate-400 italic text-xs">Sin teléfono registrado</div>'}

            ${client.notes ? `
              <div class="flex items-start gap-1.5 text-slate-500 italic">
                <span class="text-slate-400">📝</span>
                <span class="line-clamp-2">${escapeHtml(client.notes)}</span>
              </div>
            ` : ''}

            ${lastCreditDate ? `
              <div class="flex items-center gap-1.5 text-slate-500">
                <span class="text-slate-400">📅</span>
                <span>Último consumo: ${formatDate(lastCreditDate)}</span>
              </div>
            ` : ''}
          </div>

          <!-- Resumen de montos -->
          <div class="bg-slate-50 rounded-xl p-3 border border-slate-100 grid grid-cols-2 gap-2 mb-4">
            <div>
              <p class="text-[11px] text-slate-500 uppercase tracking-wider font-semibold">Total Consumido</p>
              <p class="text-sm font-semibold text-slate-700">${formatCurrency(totalCredit)}</p>
            </div>
            <div>
              <p class="text-[11px] text-slate-500 uppercase tracking-wider font-semibold">Saldo Pendiente</p>
              <p class="text-base font-bold ${balanceColor}">${formatCurrency(balance)}</p>
            </div>
          </div>
        </div>

        <!-- Acciones directas -->
        <div class="pt-3 border-t border-slate-100 flex flex-col gap-2">
          <!-- Botón estrella: Generar Reporte / Cobrar -->
          <button 
            onclick="openClientBillingReport('${client.id}')"
            class="w-full py-2.5 px-3 ${balance > 0 ? 'bg-red-600 hover:bg-red-700 text-white' : 'bg-slate-800 hover:bg-slate-900 text-white'} rounded-xl text-xs font-bold flex items-center justify-center gap-1.5 transition-colors shadow-sm">
            <span>📄</span>
            <span>${balance > 0 ? 'Generar Reporte para Cobrar' : 'Ver Historial y Estado'}</span>
          </button>

          <div class="grid grid-cols-3 gap-1.5">
            <button 
              onclick="quickAddCreditModal('${client.id}')" 
              class="py-1.5 px-2 bg-amber-50 hover:bg-amber-100 text-amber-800 rounded-lg text-xs font-semibold flex items-center justify-center gap-1"
              title="Anotar plato o comida fiada">
              <span>🍲</span> Fiado
            </button>
            <button 
              onclick="quickAddPaymentModal('${client.id}')" 
              class="py-1.5 px-2 bg-emerald-50 hover:bg-emerald-100 text-emerald-800 rounded-lg text-xs font-semibold flex items-center justify-center gap-1"
              title="Registrar abono de dinero">
              <span>💵</span> Abono
            </button>
            <button 
              onclick="editClient('${client.id}')" 
              class="py-1.5 px-2 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-lg text-xs font-semibold flex items-center justify-center gap-1"
              title="Editar datos del cliente">
              <span>✏️</span> Editar
            </button>
          </div>
        </div>
      </div>
    `;
  }).join('');
}

// --- POBLAR SELECTS DE CLIENTES EN FORMULARIOS ---
function populateClientSelects() {
  const creditSelect = document.getElementById('credit-client-id');
  const paymentSelect = document.getElementById('payment-client-id');

  const optionsHtml = '<option value="">-- Selecciona un comensal / cliente --</option>' + 
    appState.clients
      .slice()
      .sort((a, b) => a.name.localeCompare(b.name))
      .map(c => {
        const { balance } = getClientBalance(c.id);
        const debtTxt = balance > 0 ? ` (Debe: ${formatCurrency(balance)})` : ' (Al día)';
        return `<option value="${c.id}">${escapeHtml(c.name)}${c.alias ? ` [${escapeHtml(c.alias)}]` : ''}${debtTxt}</option>`;
      }).join('');

  if (creditSelect) creditSelect.innerHTML = optionsHtml;
  if (paymentSelect) paymentSelect.innerHTML = optionsHtml;
}

// --- GESTIÓN DE CLIENTES (CREAR / EDITAR / ELIMINAR) ---
function handleSaveClient(event) {
  event.preventDefault();
  const idInput = document.getElementById('client-form-id');
  const name = document.getElementById('client-name').value.trim();
  const alias = document.getElementById('client-alias').value.trim();
  const phone = document.getElementById('client-phone').value.trim();
  const notes = document.getElementById('client-notes').value.trim();
  const creditLimit = parseFloat(document.getElementById('client-limit').value) || 0;

  if (!name) {
    showToast('El nombre del cliente es obligatorio', 'warning');
    return;
  }

  const isEdit = idInput && idInput.value;

  if (isEdit) {
    const client = appState.clients.find(c => c.id === idInput.value);
    if (client) {
      client.name = name;
      client.alias = alias;
      client.phone = phone;
      client.notes = notes;
      client.creditLimit = creditLimit;
      showToast('Cliente actualizado correctamente');
    }
  } else {
    const newClient = {
      id: 'cli-' + Date.now(),
      name,
      alias,
      phone,
      creditLimit,
      notes,
      createdAt: new Date().toISOString()
    };
    appState.clients.push(newClient);
    showToast('Nuevo cliente registrado');
  }

  saveData();
  closeModal('modal-add-client');
  renderClientsList();
  populateClientSelects();
  document.getElementById('client-form').reset();
  if (idInput) idInput.value = '';
}

function editClient(clientId) {
  const client = appState.clients.find(c => c.id === clientId);
  if (!client) return;

  document.getElementById('client-form-id').value = client.id;
  document.getElementById('client-name').value = client.name || '';
  document.getElementById('client-alias').value = client.alias || '';
  document.getElementById('client-phone').value = client.phone || '';
  document.getElementById('client-limit').value = client.creditLimit || '';
  document.getElementById('client-notes').value = client.notes || '';

  document.getElementById('modal-client-title').textContent = 'Editar Cliente';
  document.getElementById('btn-delete-client').classList.remove('hidden');

  openModal('modal-add-client');
}

function deleteCurrentClient() {
  const id = document.getElementById('client-form-id').value;
  if (!id) return;

  const client = appState.clients.find(c => c.id === id);
  if (!client) return;

  const { balance } = getClientBalance(id);
  let confirmMsg = `¿Deseas eliminar al cliente "${client.name}"?`;
  if (balance > 0) {
    confirmMsg += `\n⚠️ ATENCIÓN: Tiene un saldo pendiente por cobrar de ${formatCurrency(balance)}. También se eliminarán sus registros.`;
  }

  if (confirm(confirmMsg)) {
