// --- EXPORTAR A EXCEL (CSV) ---
function exportDebtorsToCSV() {
  const debtors = appState.clients
    .map(c => ({
      client: c,
      stats: getClientBalance(c.id)
    }))
    .filter(item => item.stats.balance > 0)
    .sort((a, b) => b.stats.balance - a.stats.balance);

  if (debtors.length === 0) {
    showToast('No hay cuentas pendientes para exportar', 'warning');
    return;
  }

  let csvContent = '\uFEFF'; // BOM para que Excel reconozca tildes en UTF-8
  csvContent += 'No,Nombre,Referencia / Empresa,Telefono,Ultimo Consumo,Total Consumido,Total Abonado,Saldo Pendiente\n';

  debtors.forEach((item, index) => {
    const { client, stats } = item;
    const cleanName = `"${(client.name || '').replace(/"/g, '""')}"`;
    const cleanAlias = `"${(client.alias || '').replace(/"/g, '""')}"`;
    const cleanPhone = `"${(client.phone || '').replace(/"/g, '""')}"`;
    const lastDate = stats.lastCreditDate ? formatDate(stats.lastCreditDate) : 'N/A';

    csvContent += `${index + 1},${cleanName},${cleanAlias},${cleanPhone},${lastDate},${stats.totalCredit.toFixed(2)},${stats.totalPaid.toFixed(2)},${stats.balance.toFixed(2)}\n`;
  });

  const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.setAttribute('href', url);
  link.setAttribute('download', `reporte_cobranza_${new Date().toISOString().slice(0, 10)}.csv`);
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  showToast('Archivo CSV generado y descargado para Excel');
}

